import Table from "@/components/DashboardTable";
import SummaryCards from "@/components/SummaryCards";
import { useDashboardApi } from "@/lib/useDashboardApi";
import { MobileOutlined, WifiOutlined, DisconnectOutlined, CheckCircleOutlined, StopOutlined } from "@ant-design/icons";
import { useTableState } from "@/lib/useTableState";
import { phoneSearchQuery, readPhoneSearchState } from "@/lib/phoneSearchState";
import {
  ReactElement,
  Key,
  SetStateAction,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import { Alert, Button, Flex, Modal, notification, Space, Switch, Tag } from "antd";
import { ColumnsType } from "antd/es/table";
import dayjs from "dayjs";
import { useSession } from "next-auth/react";
import { i18n, useTranslation } from "next-i18next";
import { serverSideTranslations } from "next-i18next/serverSideTranslations";
import { useRouter } from "next/router";

import Layout from "@/components/Layout";
import ModalQrCode from "@/components/phone/ModalQrCode";
import TestSendModal from "@/components/phone/TestSendModal";
import PhoneFormModal, {
  PhoneFormData,
  PhoneFormModalRef,
} from "@/components/phone/PhoneFormModal";
import PhoneTableButton from "@/components/phone/PhoneTableButton";
import SearchPhoneForm from "@/components/phone/SearchPhoneForm";
import usePhoneData from "@/lib/usePhoneData";
import type { PhoneRow } from "@/lib/usePhoneData";
import { isSuperAdmin } from "@/lib/access";
import useSocket, { SocketEvent } from "@/lib/useSocket";
import { copyToClipboard } from "@/utils/copyToClipboard";
import { Phone } from "@prisma/client";

const PhonePage = () => {
  const router = useRouter();
  const searchState = readPhoneSearchState(router.query);
  const replaceSearch = (next: typeof searchState) => {
    void router.replace({ pathname: router.pathname, query: phoneSearchQuery(next) }, undefined, { shallow: true, scroll: false });
  };
  const table = useTableState({ value: searchState.table, onChange: next => replaceSearch({ ...searchState, table: next }) });
  const [testPhone, setTestPhone] = useState<Phone>();
  const [state, setState] = useState<{
    openForm: boolean;
    openReplyForm: boolean;
    formLoading: boolean;
    openQrModal: boolean;
    selectedPhone: Phone | undefined;
    editPhone: Phone | undefined;
    phoneId: Phone | undefined;
  }>({
    openForm: false,
    openReplyForm: false,
    formLoading: false,
    openQrModal: false,
    selectedPhone: undefined,
    editPhone: undefined,
    phoneId: undefined,
  });
  const { data: session } = useSession();
  const summary = useDashboardApi<{ total: number; online: number; offline: number; active: number; inactive: number }>("/api/phones?summary=1", 10000);
  const admin = !!session?.user && isSuperAdmin({
    id: session.user.id, email: session.user.email,
    role: session.user.role || "USER", approvalStatus: session.user.approvalStatus || "",
  });

  const searchQuery = searchState.filters;
  const phoneData = usePhoneData(session?.user?.token!, { ...searchQuery, page: table.page, limit: table.limit, sort: table.sort, order: table.order });
  const showSearch = searchState.showSearch;
  const socketOption = useMemo(() => session?.user?.id ? {
    path: "/socket.io",
    autoConnect: false,
    transports: ["websocket"],
  } : undefined, [session?.user?.id]);
  const { socket, setEvents } = useSocket(socketOption);
  const refreshPhones = useRef(phoneData.refetchPhone);
  refreshPhones.current = phoneData.refetchPhone;
  const { t } = useTranslation("common");
  const [modal, contextHolder] = Modal.useModal();
  const [notif, notificationContext] = notification.useNotification();
  const form = useRef<PhoneFormModalRef>(null);
  const [selectedPhoneIds, setSelectedPhoneIds] = useState<Key[]>([]);
  const [generatingTokens, setGeneratingTokens] = useState(false);
  const generatingRef = useRef(false);

  useEffect(() => { setSelectedPhoneIds([]); }, [session?.user?.id]);

  const confirmGenerateTokens = (ids?: string[], phone?: PhoneRow) => {
    const all = !ids;
    const target = all ? (admin ? "semua nomor dari seluruh pemilik" : "semua nomor milik Anda")
      : phone ? `nomor ${phone.number || phone.name}` : `${ids.length} nomor yang dipilih`;
    modal.confirm({
      title: `Generate token untuk ${target}?`,
      content: `Token lama untuk ${target} akan langsung diganti. Perbarui token pada integrasi API Anda setelah selesai.${all ? " Berlaku untuk seluruh nomor, termasuk di halaman lain dan di luar hasil pencarian." : ""}`,
      okText: "Generate Token", cancelText: "Batal",
      onOk: async () => {
        if (generatingRef.current) return;
        generatingRef.current = true;
        setGeneratingTokens(true);
        try {
          const result = await phoneData.generateTokens(ids ? { scope: "selected", ids } : { scope: "all" });
          if (!result.success) {
            notif.error({ message: "Generate token gagal", description: result.error?.response?.data?.message || "Hasil belum dapat dipastikan. Muat ulang untuk memeriksa token sebelum mencoba lagi." });
            throw new Error("Generate token gagal");
          }
          setSelectedPhoneIds(current => all ? [] : current.filter(id => !ids!.includes(String(id))));
          notif.success({ message: `Token baru berhasil dibuat untuk ${result.data.count} nomor.` });
        } finally {
          generatingRef.current = false;
          setGeneratingTokens(false);
        }
      },
    });
  };

  useEffect(() => {
    if (!session?.user?.id) return;
    const timer = setInterval(() => {
      if (document.visibilityState === "visible") refreshPhones.current();
    }, 10000);
    return () => clearInterval(timer);
  }, [session?.user?.id]);

  useEffect(() => {
    if (!socketOption || state.openForm || state.openQrModal) {
      setEvents([]);
      socket?.disconnect();
      return;
    }
    const events: SetStateAction<SocketEvent[] | null> = [];

    events.push({
      name: `isOnline`,
      handler: (connection) => {
        if (typeof connection.isOnline === "boolean") refreshPhones.current();
      },
    });
    events.push({
      name: `waUser`,
      handler: () => refreshPhones.current(),
    });

    events.push({
      name: "connect",
      handler: () => {
        refreshPhones.current();
      },
    });
    setEvents(events);
    socket?.connect();
    return () => {
      setEvents([]);
      socket?.disconnect();
    };
  }, [socketOption, state.openForm, state.openQrModal]);

  const dataColumn: ColumnsType<PhoneRow> = [
    {
      title: t("number"),
      key: "number",
      dataIndex: "number",
    },
    {
      title: t("account_name"),
      key: "account_name",
      dataIndex: "account_name",
      render: (v) => <div style={{ whiteSpace: "nowrap" }}>{v}</div>,
    },
    {
      title: t("phone_label"),
      key: "name",
      dataIndex: "name",
      render: (v) => <div style={{ whiteSpace: "nowrap" }}>{v}</div>,
    },
    {
      title: "Status",
      key: "isOnline",
      dataIndex: "isOnline",
      render: (v) => v ? (
        <Tag style={{ background: "#39ff14", color: "#135200", borderColor: "#52c41a", fontWeight: 700, boxShadow: "0 0 8px rgba(57, 255, 20, 0.45)" }}>
          Online
        </Tag>
      ) : "Offline",
    },
    {
      title: "Status Perangkat",
      key: "active",
      dataIndex: "active",
      render: (v) => (
        <Tag color={v === 1 ? "green" : "red"}>
          {v === 1 ? "Aktif" : "Tidak Aktif"}
        </Tag>
      ),
    },
    {
      title: "Save Group",
      key: "is_save_group",
      dataIndex: "is_save_group",
      render: (v, phone) => (
        <Switch
          defaultChecked={v ? true : false}
          checkedChildren="On"
          unCheckedChildren="Off"
          onChange={(checked) => {
            onSaveGroup(phone, checked);
            // setIsSendGroup({
            //   phoneId: String(phone.id),
            //   is_send_group: checked,
            // })
          }}
        />
      ),
    },
    {
      title: t("api_token"),
      key: "token",
      dataIndex: "token",

      render: (v, phone) => (
        <Space direction="horizontal" style={{ whiteSpace: "nowrap" }}>
          <Button
            onClick={async () => {
              await copyToClipboard({ value: v });
              notif.destroy();
              notif.success({
                closeIcon: false,
                duration: 3,
                message:
                  t("text_copied", { text: '"Token"' }).toString() || "Copied",
                placement: "bottom",
              });
            }}
          >
            Copy
          </Button>
          <Button disabled={generatingTokens} onClick={() => confirmGenerateTokens([phone.id], phone)}>
            Generate Token
          </Button>
          <div>{v}</div>
        </Space>
      ),
    },
    ...(admin ? [{
      title: "Kepemilikan",
      key: "user.name",
      dataIndex: ["user", "name"],
      width: 220,
      render: (_: unknown, phone: PhoneRow) => <div style={{ minWidth: 160, maxWidth: 240, overflowWrap: "anywhere" }}>
        <div>{phone.user?.name || phone.user?.email || phone.userId}</div>
        {phone.user?.name && phone.user?.email && <div style={{ color: "var(--ui-muted)", fontSize: 12 }}>{phone.user.email}</div>}
      </div>,
    }] : []),
    {
      title: t("created_at"),
      key: "createdAt",
      dataIndex: "createdAt",
      render: (v) => (
        <div style={{ whiteSpace: "nowrap" }}>
          {dayjs(v).format("DD/MM/YYYY HH:mm")}
        </div>
      ),
    },
    {
      title: t("action"),
      key: "action",
      dataIndex: "id",
      fixed: "right",
      render: (v, phone) => {
        return (
          <PhoneTableButton
            phone={phone}
            // onAutoReply={
            //   (_phone: Phone | undefined) => {
            //     _phone &&
            //       setState({...state, openReplyForm: true, phoneId: _phone })
            //   }
            // }
            onListReply={(_phone: Phone | undefined) =>
              router.push({
                pathname: "/dashboard/auto-reply",
                query: {
                  phone_id: _phone?.id,
                  phone_num: _phone?.number,
                  phone_search: new URLSearchParams(phoneSearchQuery(searchState)).toString(),
                },
              })
            }
            onEditClick={onEditClick}
            onDeleteClick={onDeleteClick}
            onGetQrCodeClick={onGetQrCodeClick}
            onToggleActiveClick={onToggleActiveClick}
            onTestSendClick={phone => setTestPhone(phone)}
          />
        );
      },
    },
  ];

  const onSubmit = async (data: PhoneFormData) => {
    setState({ ...state, formLoading: true });
    const res = await phoneData.save(data);
    if (res.success) {
      form.current?.resetForm();
    } else {
      notif.error({ message: "Device belum tersimpan", description: res.error?.response?.data?.message || "Coba lagi." });
      setState({ ...state, formLoading: false });
      return;
    }
    setState({
      ...state,
      formLoading: false,
      openForm: false,
      editPhone: undefined,
    });
  };

  const onCancel = () =>
    setState({
      ...state,
      openForm: false,
      editPhone: undefined,
      openReplyForm: false,
      phoneId: undefined,
    });

  const onEditClick = (_phone: Phone | undefined) => {
    _phone && setState({ ...state, editPhone: _phone, openForm: true });
  };

  const onDeleteClick = (_phone: Phone | undefined) => {
    _phone &&
      modal.confirm({
        title: t("confirm_delete"),
        content: t("confirm_delete_ask"),
        onOk: async () => {
          const result = await phoneData.deleteById(_phone.id);
          notif[result.success ? "success" : "error"]({
            message: result.success ? t("success") : t("failed"),
            description: result.success
              ? t("success_delete")
              : t("failed_delete"),
          });
        },
      });
  };

  const onToggleActiveClick = (_phone: Phone | undefined, active: number) => {
    if (_phone) {
      modal.confirm({
        title: active === 1 ? "Konfirmasi Aktifkan Perangkat" : "Konfirmasi Nonaktifkan Perangkat",
        content: `Apakah Anda yakin ingin ${active === 1 ? "mengaktifkan" : "menonaktifkan"} perangkat ${_phone.name}?`,
        onOk: async () => {
          const result = await phoneData.toggleActive(_phone.id, active);
          notif[result.success ? "success" : "error"]({
            message: result.success ? t("success") : t("failed"),
            description: result.success
              ? `Perangkat berhasil ${active === 1 ? "diaktifkan" : "dinonaktifkan"}`
              : `Gagal ${active === 1 ? "mengaktifkan" : "menonaktifkan"} perangkat`,
          });
        },
      });
    }
  };

  const onSaveGroup = (_phone: Phone | undefined, checked: boolean) => {
    // const enable_save_group = async (data: PhoneFormData) => {
    //   const result = await phoneData.save(data);
    //   if(result.success) {
    //
    //   }
    // }
    const enable_save_group = async (
      phoneId: string,
      is_save_group: boolean
    ) => {
      const result = await phoneData.isSaveGroup(phoneId, is_save_group);
      if (result.success) {
      }
    };

    if (_phone) {
      // const data = {..._phone, is_save_group: checked};
      // enable_save_group(data);
      const { id } = _phone;
      enable_save_group(id, checked);
    }
  };

  const onGetQrCodeClick = (_phone: Phone | undefined) => {
    _phone &&
      setState({
        ...state,
        selectedPhone: _phone,
        openQrModal: true,
      });
  };

  return (
    <>
      <Flex gap="middle" vertical>
        <SummaryCards title="Ringkasan perangkat" caption="Seluruh perangkat yang dapat diakses akun Anda • diperbarui otomatis setiap 10 detik" items={[
          { key: "total", label: "Jumlah perangkat", value: summary.data?.total, color: "#1684d6", icon: <MobileOutlined /> },
          { key: "online", label: "Online", value: summary.data?.online, color: "#20a66a", icon: <WifiOutlined /> },
          { key: "offline", label: "Offline", value: summary.data?.offline, color: "#8b94a5", icon: <DisconnectOutlined /> },
          { key: "active", label: "Aktif", value: summary.data?.active, color: "#7464d9", icon: <CheckCircleOutlined /> },
          { key: "inactive", label: "Tidak aktif", value: summary.data?.inactive, color: "#df8a26", icon: <StopOutlined /> },
        ]} />
        {summary.error && <Alert type="error" showIcon message={summary.error} />}
        <Flex gap="middle" wrap="wrap">
          <Button
            type="primary"
            onClick={() => setState({ ...state, openForm: true })}
          >
            {t("add_devices")}
          </Button>
          <Button onClick={() => replaceSearch({ ...searchState, showSearch: !showSearch })}>
            {showSearch ? t("hide_search") : t("show_search")}
          </Button>
          <Button disabled={!selectedPhoneIds.length || generatingTokens} onClick={() => confirmGenerateTokens(selectedPhoneIds.map(String))}>
            Generate Token Terpilih ({selectedPhoneIds.length})
          </Button>
          <Button disabled={generatingTokens} onClick={() => confirmGenerateTokens()}>
            Generate Token Semua Nomor
          </Button>
          {!!selectedPhoneIds.length && <Button disabled={generatingTokens} onClick={() => setSelectedPhoneIds([])}>Hapus Pilihan</Button>}
        </Flex>
        <PhoneFormModal
          ref={form}
          loading={state.formLoading}
          open={state.openForm}
          onCancel={onCancel}
          onSubmit={onSubmit}
          editPhone={state.editPhone}
        />
        {/* <AutoReplyFormModal
      ref={formAutoRep}
      loading={state.formLoading}
      open={state.openReplyForm}
      onCancel={onCancel}
      onSubmitReply={onSubmitReply}
      onChangeImageReply={handleTambahImageReply}
      phoneId={state.phoneId} 
      />*/}
        <SearchPhoneForm
          visible={showSearch}
          initialValues={searchQuery}
          onSubmitSuccess={(data) => {
            replaceSearch({ ...searchState, filters: { name: data.name || "", number: data.number || "", is_online: data.is_online || "", active: data.active || "" }, table: { ...searchState.table, page: 1 } });
          }}
        />
        <Alert
          type="info"
          showIcon
          message="Tentang Save Group"
          description={
            <Space direction="vertical" size={4}>
              <span><strong>On:</strong> saat nomor perangkat menerima pesan dari grup WhatsApp, Jeblast menyimpan grup yang belum tercatat, termasuk ID, nama, deskripsi, dan daftar anggotanya.</span>
              <span><strong>Off:</strong> penyimpanan data grup otomatis dinonaktifkan.</span>
              <span>Penyimpanan dipicu oleh pesan masuk dari grup, bukan langsung mengambil semua grup saat diaktifkan. Fitur ini tidak mencadangkan riwayat chat atau mengirim blast otomatis.</span>
            </Space>
          }
        />
        <Table
          className="table-with-data-count"
          scroll={{ x: true }}
          onRow={(record) => {
            return {
              onContextMenu: (event) => {
                event.preventDefault();
                //
              },
            };
          }}
          dataSource={phoneData.phones}
          columns={dataColumn}
          rowKey="id"
          rowSelection={{
            selectedRowKeys: selectedPhoneIds,
            preserveSelectedRowKeys: true,
            onChange: keys => setSelectedPhoneIds(keys),
            getCheckboxProps: () => ({ disabled: generatingTokens }),
          }}
          table={table}
          total={phoneData.total}
        />
        <ModalQrCode
          onConnected={phoneData.refetchPhone}
          onActivated={phoneData.refetchPhone}
          token={session?.user?.token!}
          userId={session?.user?.id}
          open={state.openQrModal}
          phone={state.selectedPhone || undefined}
          onClose={() => { setState({ ...state, openQrModal: false }); refreshPhones.current(); }}
        />
        <TestSendModal open={!!testPhone} phone={testPhone} token={session?.user?.token}
          onClose={() => setTestPhone(undefined)} />

        {contextHolder}
        {notificationContext}
      </Flex>
    </>
  );
};

export const getStaticProps = async ({ locale }: { locale: string }) => ({
  props: {
    ...(await serverSideTranslations(locale, ["common", "upgrade"])),
  },
});

PhonePage.getLayout = function getLayout(page: ReactElement) {
  const title = () => i18n?.t("phone_devices") || "";
  return <Layout title={title().toUpperCase()}>{page}</Layout>;
};

export default PhonePage;

