import { prisma } from "@/lib/prisma";
import { ownerScope } from "@/lib/access";
import apiAuthMiddleware from "@/middleware/apiAuthMiddleware";
import { AuthNextApiRequest } from "@/types/global";
import type { NextApiResponse } from "next";
import { enqueueDeviceEvent } from "@/server/deviceWebhook/events";
async function handler(req: AuthNextApiRequest, res: NextApiResponse) {
  if (req.method !== "DELETE") return res.status(405).end();
  const deleted = await prisma.$transaction(async tx => {
    await tx.$queryRaw`SELECT id FROM device_webhook_settings WHERE id = 1 FOR UPDATE`;
    const where = { id: String(req.query.id), ...ownerScope(req.user!) };
    await tx.$queryRaw`SELECT id FROM phones WHERE id = ${where.id} FOR UPDATE`;
    const phone = await tx.phone.findFirst({ where });
    if (!phone) return false;
    const result = await tx.phone.deleteMany({ where });
    if (!result.count) return false;
    await enqueueDeviceEvent(tx, "device.deleted", phone);
    return true;
  });
  if (!deleted) return res.status(404).json({ message: "Data tidak ditemukan." });
  return res.json({ result: true });
}
export default apiAuthMiddleware(handler);

